    _ruta_sk = str(p.get("archivo") or "")
    if (_ruta_sk.lower().endswith(".py") and os.path.isfile(_ruta_sk)
            and viejo.strip()):
        with open(_ruta_sk, encoding="utf-8-sig", errors="replace") as _fsk:
            _antes_sk = _fsk.read()
        if viejo in _antes_sk:
            _despues_sk = _antes_sk.replace(viejo, nuevo, 1)
            _arbol_sk = ast.parse(_despues_sk)

            _PALABRAS_NO_EXISTE = ("no existe", "todavia", "aun no", "no esta",
                                  "falta", "pendiente", "no implementad")

            def _mensaje_habla_de_que_no_existe(_nodo):
                for _h in ast.walk(_nodo):
                    if isinstance(_h, ast.Constant) and isinstance(_h.value, str):
                        _m = _h.value.lower()
                        for _p in _PALABRAS_NO_EXISTE:
                            if _p in _m:
                                return True
                return False

            def _llama_a_skip(_nodo):
                for _h in ast.walk(_nodo):
                    if isinstance(_h, ast.Call):
                        _f = _h.func
                        if isinstance(_f, ast.Attribute) and _f.attr == "skip":
                            return True
                        if isinstance(_f, ast.Name) and _f.id == "SkipTest":
                            return True
                return False

            for _n in ast.walk(_arbol_sk):
                if (isinstance(_n, (ast.FunctionDef, ast.AsyncFunctionDef))
                        and _n.name.startswith("test_")
                        and _llama_a_skip(_n)
                        and _mensaje_habla_de_que_no_existe(_n)):
                    fallos.append(
                        "PRUEBA SALTADA PORQUE LA PIEZA NO EXISTE TODAVIA: la prueba "
                        "'%s' se salta diciendo que la pieza no existe todavia. Una "
                        "prueba saltada no puede ponerse roja: mientras la pieza no "
                        "exista tiene que fallar con assert." % _n.name)
except Exception:
    pass

